"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["77593"],{18759(e){e.exports=JSON.parse('{"id":"FIN-1204","slug":"tax-lot","term":"Tax Lot","also_known_as":[],"difficulty":"Advanced","definition":"A tax lot is a record of a specific purchase of a security, including the date, quantity and price paid, used to calculate the gain or loss when part of a holding is sold.","explanation":["Investors often build a position by buying the same shares or fund at different times and prices. Each purchase is a separate tax lot. When only part of the holding is sold, the investor or broker must decide which lots were sold, which affects the gain or loss.","For example, an investor bought 100 shares at 20 and later another 100 at 35. They now sell 100 shares at 30. If the first lot is treated as sold, the gain is 1,000. If the second lot is treated as sold, there is a loss of 500.","Common methods include first-in, first-out, which treats the oldest lots as sold first; average cost, often used for mutual funds; and specific identification, where the investor chooses the lots, which allows them to manage taxes, for example by selling high-cost lots to reduce gains.","The rules vary by country. In the United Kingdom, for example, shares of the same company are usually pooled at an average cost rather than tracked as separate lots. Brokers record lot information, but the chosen method must be applied consistently and in time."],"note":"","total":1500,"prev":{"slug":"tax-loss-harvesting","term":"Tax-Loss Harvesting"},"next":{"slug":"tax-provision","term":"Tax Provision"}}')}}]);